    85→function extractChapBytes(buffer, fieldName, nextFieldName) {
    86→  const startMarkers = [
    87→    Buffer.from(`"${fieldName}": "`),
    88→    Buffer.from(`"${fieldName}":"`),
    89→  ];
    90→
    91→  let startIdx = -1;
    92→  for (const m of startMarkers) {
    93→    const idx = buffer.indexOf(m);
    94→    if (idx !== -1) { startIdx = idx + m.length; break; }
    95→  }
    96→  if (startIdx === -1) return Buffer.alloc(0);
    97→
    98→  const endSeparators = [
    99→    Buffer.from(`",\r\n\t"${nextFieldName}"`),
   100→    Buffer.from(`",\n\t"${nextFieldName}"`),
   101→    Buffer.from(`",\r\n        "${nextFieldName}"`),
   102→    Buffer.from(`",\n        "${nextFieldName}"`),
   103→    Buffer.from(`",\r\n"${nextFieldName}"`),
   104→    Buffer.from(`",\n"${nextFieldName}"`),
   105→  ];
   106→
   107→  for (const sep of endSeparators) {
   108→    const idx = buffer.indexOf(sep, startIdx);
   109→    if (idx !== -1) {
   110→      return buffer.slice(startIdx, idx);
   111→    }
   112→  }
   113→
   114→  return Buffer.alloc(0);
   115→}
