   117→function cleanJsonForParsing(buffer) {
   118→  let latin1 = buffer.toString('latin1');
   119→
   120→  const chapFields = [
   121→    { field: 'chapId', next: 'chapChallenge' },
   122→    { field: 'chapChallenge', next: 'isLogin' },
   123→  ];
   124→
   125→  for (const { field, next } of chapFields) {
   126→    const startMarkers = [`"${field}": "`, `"${field}":"`];
   127→    for (const marker of startMarkers) {
   128→      const idx = latin1.indexOf(marker);
   129→      if (idx === -1) continue;
   130→      const start = idx + marker.length;
   131→
   132→      const endPatterns = [
   133→        `",\r\n\t"${next}"`,
   134→        `",\n\t"${next}"`,
   135→        `",\r\n        "${next}"`,
   136→        `",\n        "${next}"`,
   137→        `",\r\n"${next}"`,
   138→        `",\n"${next}"`,
   139→      ];
   140→
   141→      for (const ep of endPatterns) {
   142→        const endIdx = latin1.indexOf(ep, start);
   143→        if (endIdx !== -1) {
   144→          latin1 = latin1.substring(0, start) + latin1.substring(endIdx);
   145→          break;
   146→        }
   147→      }
   148→      break;
   149→    }
   150→  }
   151→
   152→  return latin1;
   153→}
