   155→function parseHotspotResponse(buffer) {
   156→  const chapIdBytes = extractChapBytes(buffer, 'chapId', 'chapChallenge');
   157→  const chapChallengeBytes = extractChapBytes(buffer, 'chapChallenge', 'isLogin');
   158→
   159→  let data = {};
   160→  try {
   161→    const cleaned = cleanJsonForParsing(buffer);
   162→    data = JSON.parse(cleaned);
   163→  } catch (e) {
   164→    const latin1 = buffer.toString('latin1');
   165→    data = manualExtract(latin1);
   166→  }
   167→
   168→  data.chapIdHex = chapIdBytes.toString('hex');
   169→  data.chapChallengeHex = chapChallengeBytes.toString('hex');
   170→  delete data.chapId;
   171→  delete data.chapChallenge;
   172→
   173→  return data;
   174→}
