   176→function manualExtract(str) {
   177→  const data = {};
   178→  const fields = ['loginLink', 'mac', 'ip', 'interfaceName', 'serverAddress', 'error',
   179→                  'logoutLink', 'username', 'sessionTimeLeft', 'uptime'];
   180→  for (const f of fields) {
   181→    const regex = new RegExp(`"${f}"\\s*:\\s*"([^"]*)"`);
   182→    const match = str.match(regex);
   183→    if (match) data[f] = match[1];
   184→  }
   185→  data.isLogin = str.includes('"isLogin": true') || str.includes('"isLogin":true');
   186→  const unitsMatch = str.match(/"units"\s*:\s*(\{[^}]*\})/);
   187→  if (unitsMatch) {
   188→    try { data.units = JSON.parse(unitsMatch[1]); } catch (_) {}
   189→  }
   190→  return data;
   191→}
