// While the lock screen is active, no other application may hold the
// foreground. Exclusive-fullscreen games (e.g. GTA) can render ABOVE an
// always-on-top "screen-saver" level window, visually bypassing the lock.
// To defeat that, we poll the foreground window and force-minimize any window
// that does not belong to our own process, then reclaim focus to the lock UI.
let lockEnforcementInterval = null;

function startLockEnforcement() {
  if (process.platform !== 'win32') return;
  if (lockEnforcementInterval) return;
  const selfName = path.basename(app.getPath('exe')).replace(/\.exe$/i, '').toLowerCase();
  const psCmd = 'powershell -NoProfile -Command "'
    + '$sig = Add-Type -MemberDefinition \'[DllImport(\\\"user32.dll\\\")] public static extern IntPtr GetForegroundWindow(); '
    + '[DllImport(\\\"user32.dll\\\")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint pid); '
    + '[DllImport(\\\"user32.dll\\\")] public static extern bool ShowWindowAsync(IntPtr hWnd, int nCmd);\' -Name W -Namespace W -PassThru; '
    + '$h = [W.W]::GetForegroundWindow(); $fpid = 0; [W.W]::GetWindowThreadProcessId($h, [ref]$fpid) | Out-Null; '
    + '$n = (Get-Process -Id $fpid -EA SilentlyContinue).ProcessName; '
    + 'if ($n -and $n.ToLower() -ne \'' + selfName + '\') { [W.W]::ShowWindowAsync($h, 11) | Out-Null; Write-Output $n }"';

  lockEnforcementInterval = setInterval(() => {
    if (currentState !== 'logged-out') return;
    exec(psCmd, { timeout: 2500, windowsHide: true }, (err, stdout) => {
      if (currentState !== 'logged-out') return;
      const foreign = (stdout || '').trim();
      if (foreign) {
        console.log('[Lock] Minimized foreground app during lock:', foreign);
        reclaimFocus();
      }
    });
  }, 1500);
  console.log('[Lock] Foreground enforcement started.');
}

function stopLockEnforcement() {
  if (lockEnforcementInterval) {
    clearInterval(lockEnforcementInterval);
    lockEnforcementInterval = null;
    console.log('[Lock] Foreground enforcement stopped.');
  }
}

