.login-panel.hidden { display: none; }
.login-panel.form-collapsed { display: none; }
#login-panel:not(.hidden):not(.form-collapsed) {
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(7px);
  animation: form-fade-in 0.4s ease;
}
@keyframes form-fade-in { from { opacity: 0; } to { opacity: 1; } }

/* ===== Tap-to-login launcher ===== */
#login-launcher {
  position: fixed; inset: 0; z-index: 3;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 32px; padding: 24px;
  opacity: 1; transition: opacity 0.4s ease;
}
#login-launcher.hidden { opacity: 0; pointer-events: none; visibility: hidden; }
.launcher-name {
  font-family: 'Orbitron', sans-serif; font-weight: 700;
  font-size: clamp(22px, 4vw, 44px); letter-spacing: 4px;
  color: var(--login-color, #ff8c00);
  text-shadow: 0 0 18px var(--login-color-50, rgba(255,140,0,0.5)), 0 2px 8px rgba(0,0,0,0.8);
  text-align: center;
}
.launcher-btn {
  position: relative; cursor: pointer; -webkit-app-region: no-drag;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  width: 200px; height: 200px; border-radius: 50%;
  background: rgba(12,12,20,0.55);
  border: 2px solid var(--login-color-50, rgba(255,140,0,0.5));
  color: var(--login-color, #ff8c00);
  backdrop-filter: blur(10px);
  box-shadow: 0 0 30px var(--login-color-25, rgba(255,140,0,0.25)), inset 0 0 30px rgba(0,0,0,0.4);
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
  animation: launcher-pulse 2.4s ease-in-out infinite;
}
.launcher-btn:hover {
  transform: scale(1.06);
  border-color: var(--login-color, #ff8c00);
  box-shadow: 0 0 50px var(--login-color-50, rgba(255,140,0,0.5)), inset 0 0 30px rgba(0,0,0,0.4);
}
.launcher-btn:active { transform: scale(0.98); }
@keyframes launcher-pulse {
  0%, 100% { box-shadow: 0 0 30px var(--login-color-25, rgba(255,140,0,0.25)), inset 0 0 30px rgba(0,0,0,0.4); }
  50% { box-shadow: 0 0 55px var(--login-color-50, rgba(255,140,0,0.5)), inset 0 0 30px rgba(0,0,0,0.4); }
}
.launcher-btn-icon { font-size: 58px; line-height: 1; filter: drop-shadow(0 0 12px var(--login-color-50, rgba(255,140,0,0.5))); }
.launcher-btn-label { font-family: 'Orbitron', sans-serif; font-weight: 700; font-size: 16px; letter-spacing: 3px; }
.launcher-hint {
  font-family: 'Share Tech Mono', monospace; font-size: 12px; letter-spacing: 2px;
  color: var(--login-color-50, rgba(255,140,0,0.5)); text-transform: uppercase;
}
.launcher-shutdown {
  display: flex; flex-direction: column; align-items: center; gap: 5px;
  padding: 12px 26px; border-radius: 6px;
  background: rgba(0,0,0,0.45); border: 1px solid var(--login-color-15, rgba(255,140,0,0.15));
  backdrop-filter: blur(6px);
}
.launcher-shutdown.hidden { display: none; }
.launcher-shutdown-label { font-family: 'Share Tech Mono', monospace; font-size: 10px; letter-spacing: 2px; color: var(--login-color-50, rgba(255,140,0,0.5)); text-transform: uppercase; }
.launcher-shutdown-time { font-family: 'Orbitron', sans-serif; font-weight: 700; font-size: 22px; letter-spacing: 2px; color: var(--login-color, #ff8c00); text-shadow: 0 0 12px var(--login-color-50, rgba(255,140,0,0.5)); }
.launcher-shutdown-time.danger { color: #ff4040; text-shadow: 0 0 14px rgba(255,64,64,0.6); }

.form-close-btn {
  position: absolute; top: 10px; right: 12px; z-index: 5;
  width: 34px; height: 34px; border-radius: 50%;
  background: rgba(0,0,0,0.4); border: 1px solid var(--login-color-25, rgba(255,140,0,0.25));
  color: var(--login-color, #ff8c00); font-size: 16px; line-height: 1; cursor: pointer;
  -webkit-app-region: no-drag;
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}
.form-close-btn:hover { background: rgba(0,0,0,0.7); border-color: var(--login-color, #ff8c00); transform: scale(1.08); }

